import csv
with open('data/expenses.csv', 'r') as f:
    reader = csv.DictReader(f)
    travel_expenses = []
    for row in reader:
        if row['category'] == 'Travel':
            # Check date is in 2026
            if row['date'].startswith('2026'):
                travel_expenses.append((row['id'], float(row['amount']), row['currency']))

    print(f'Total count: {len(travel_expenses)}')
    total = 0.0
    for idx, (cid, amt, curr) in enumerate(travel_expenses):
        if curr == 'GBP':
            total += amt
        elif curr == 'EUR':
            total += amt * 0.85
        elif curr == 'USD':
            total += amt * 0.79
    print(f'Total: £{total:.2f}')
